(function(){
  'use strict';
  var PRICE={x86:{gbsec:0.0000166667, req:0.0000002}, arm:{gbsec:0.0000133334, req:0.0000002}};
  var LIMITS={memMin:128, memMax:10240, timeoutMin:1, timeoutMax:900,
              epsMin:512, epsMax:10240, envCountMax:500, envSizeMax:4096};
  function vcpu(mb){ return mb/1769; }
  function validate(cfg){
    cfg=cfg||{};
    var errs=[];
    var m=cfg.mem, t=cfg.timeout, e=cfg.eps, arch=cfg.arch||'x86';
    if(m==null||m%1!==0||m<LIMITS.memMin||m>LIMITS.memMax) errs.push('内存需在 '+LIMITS.memMin+'–'+LIMITS.memMax+' MB');
    if(t==null||t%1!==0||t<LIMITS.timeoutMin||t>LIMITS.timeoutMax) errs.push('超时需在 '+LIMITS.timeoutMin+'–'+LIMITS.timeoutMax+' s');
    if(e!=null && (e<LIMITS.epsMin||e>LIMITS.epsMax)) errs.push('临时存储需在 '+LIMITS.epsMin+'–'+LIMITS.epsMax+' MB');
    if(arch!=='x86'&&arch!=='arm') errs.push('架构只能是 x86 或 arm');
    if(m!=null && m>3008 && m%512!==0) errs.push('内存 >3008 MB 时只能按 1024 MB 步进');
    return errs;
  }
  function cost(opts){
    var R=opts.requests, D=opts.durationMs, M=opts.mem, arch=opts.arch||'x86';
    if(!R||!D||!M) return {value:null,error:'请填写月请求数、平均时长(ms)、内存(MB)'};
    var gbsec=R*(D/1000)*(M/1024);
    var p=PRICE[arch]||PRICE.x86;
    var compute=gbsec*p.gbsec;
    var reqcost=R*p.req;
    var total=compute+reqcost;
    return {value:{gbsec:Math.round(gbsec*1000)/1000,
                   computeUsd:Math.round(compute*100000)/100000,
                   requestUsd:Math.round(reqcost*100000)/100000,
                   totalUsd:Math.round(total*100000)/100000, arch:arch}, error:''};
  }
  function compareCost(opts){
    var a=cost(opts), b=cost(Object.assign({},opts,{arch:'arm'}));
    if(a.error||b.error) return {value:null,error:a.error||b.error};
    var save=Math.round((1-b.value.totalUsd/a.value.totalUsd)*1000)/10;
    return {value:{x86:a.value.totalUsd, arm:b.value.totalUsd, savePct:save}, error:''};
  }
  function recommend(cfg){
    var recs=[]; var v=vcpu(cfg.mem||512);
    if(v<0.5) recs.push('当前单 vCPU 比重仅 '+Math.round(v*100)/100+'；CPU 密集型任务建议提到 1024 MB 以上以拿到更多算力');
    if(cfg.durationMs && cfg.timeout && cfg.durationMs>cfg.timeout*1000*0.8) recs.push('平均时长已接近超时上限，建议调高 timeout 或优化代码');
    if(!recs.length) recs.push('配置看起来合理');
    return recs;
  }
  function iamRole(opts){
    opts=opts||{};
    var stmts=[{Effect:'Allow',
      Action:['logs:CreateLogGroup','logs:CreateLogStream','logs:PutLogEvents'],
      Resource:'arn:aws:logs:*:*:*'}];
    if(opts.s3) stmts.push({Effect:'Allow',Action:['s3:GetObject','s3:PutObject'],
      Resource:'arn:aws:s3:::'+opts.s3+'/*'});
    if(opts.dynamo) stmts.push({Effect:'Allow',
      Action:['dynamodb:GetItem','dynamodb:PutItem','dynamodb:Query'],
      Resource:'arn:aws:dynamodb:*:*:table/'+opts.dynamo});
    var trust={Version:'2012-10-17',
      Statement:[{Effect:'Allow',Principal:{Service:'lambda.amazonaws.com'},Action:'sts:AssumeRole'}]};
    return {value:{trust:trust, policy:{Version:'2012-10-17', Statement:stmts}}, error:''};
  }
  function samSnippet(cfg){
    cfg=cfg||{};
    var s='  '+(cfg.name||'MyFunction')+':\n'+
         '    Type: AWS::Serverless::Function\n'+
         '    Properties:\n'+
         '      Runtime: '+(cfg.runtime||'nodejs22.x')+'\n'+
         '      Handler: '+(cfg.handler||'index.handler')+'\n'+
         '      MemorySize: '+(cfg.mem||512)+'\n'+
         '      Timeout: '+(cfg.timeout||30)+'\n'+
         '      Architectures: ['+(cfg.arch==='arm'?'arm64':'x86_64')+']\n';
    if(cfg.s3) s+='      # 需要访问的 S3 桶: '+cfg.s3+'\n';
    return s;
  }
  var API={PRICE:PRICE, LIMITS:LIMITS, vcpu:vcpu, validate:validate, cost:cost,
           compareCost:compareCost, recommend:recommend, iamRole:iamRole, samSnippet:samSnippet};
  if(typeof module!=='undefined' && module.exports) module.exports=API;
  if(typeof window!=='undefined') window.__LambdaForge__=API;
})();
